insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('de', 'reynisdrangar', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'In [datiert Quelle] Reynisfjara [ˈreiːnɪsˌfjaːra] wurde der sechstbeste Strand der Welt bewertet.', 'Basaltfelsnadeln unter dem Reynisfjall bei Vík í Mýrdal in Südisland, umrahmt von schwarzem Sandstrand.'),
  ('de', 'rohkunborri-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Rohkunborri National Park ist ein Nationalpark im Bezirk Troms, Norwegen, der in [datierter Quelle] eingerichtet wurde. Der Park besteht aus einem 571 Quadratkilometer großen Schutzgebiet und befindet sich in der Gemeinde Bardu an der Grenze zu Schweden, etwa 30 Kilometer südöstlich des Dorfes Setermoen und etwa 50 Kilometer nordöstlich der Stadt Narvik.', 'Der Rohkunborri-Nationalpark liegt in der Provinz Troms in Norwegen und umfasst ein Schutzgebiet von 571 Quadratkilometern. Er befindet sich in der Gemeinde Bardu an der Grenze zu Schweden, etwa 30 Kilometer südöstlich des Dorfes Setermoen und rund 50 Kilometer nordöstlich der Stadt Narvik.'),
  ('de', 'rosalia-kogelberg-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Im Rahmen des Projekts „Barrierefreies Naturerlebnis Rosalia-Kogelberg wurde zwischen [datierter Quelle] und [datierter Quelle] ein Wander- und Naturerlebnis für alle Sinne geschaffen. Das Projekt umfasste unter anderem die Konzeption und den Bau von insgesamt elf barrierefreien Erlebnis- und Ruhestationen entlang des sogenannten Eulenwegs oder entlang der „Tour Teichwiesen.', 'Im Rahmen des Projekts „Barrierefreies Naturerlebnis Rosalia-Kogelberg“ entstand ein Wander- und Naturerlebnis für alle Sinne. Dazu wurden elf barrierefreie Erlebnis- und Raststationen entlang des Eulenwegs und der „Tour Teichwiesen“ geplant und gebaut.'),
  ('de', 'saimaa-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Das Gebiet erhielt den UNESCO Global Geopark Status in [datiert Quelle].', 'Ein UNESCO Global Geopark mit 65 Geotopen rund um den Saimaa, den größten See Finnlands.'),
  ('de', 'salpausselka-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Salpausselkä Geopark wurde am 13. April angenommen [datiert Quelle].', 'Der Salpausselkä-Geopark umfasst Lahti, Hollola, Asikkala, Heinola, Sysma und Padasjoki in Finnland.'),
  ('de', 'sheskinmore-nature-reserve', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sheskinmore Nature Reserve Standort: GPS: Breitengrad: 54.794006 Längengrad: -8.463635 Sheskinmore bezieht sich auf ein großes Gebiet von Sanddünen, See und Sumpf, das zwischen Kiltooris und Ballinreavy Strand liegt, nordwestlich von Ardara, Co. Donegal. Das Gebiet ist als besonderes Schutzgebiet, als besonderes Schutzgebiet und als Wildvögelschutzgebiet ausgewiesen. Das Gebiet ist leicht vom Tor in Mullyvea gegenüber Kiltooris Lough zu erreichen. Ist ceantar mór dumcha, locha agus seascainn é Seascann Mór atá idir Cill Dorais agus Trá Bhaile an Riabhaigh ar thaobh thiar thuaidh d’Ard Ratha, Co. Dhún na nGall. Tá an ceantar ainmnithe mar Cheantar Speisialta Caomhnaithe, mar Cheantar Cosanta Speisialta agus mar Thearmann Éanlaithe. Tá sé furasta dul isteach ann tríd an geata ag Mullach Bheitheach os coinne Loch Chill Dorais. Lebensräume Das Gebiet ist meist ein festes Sanddünensystem, das Machair-Grasland, Dünenschluchten, Sheskinmore-Lough und den umliegenden Sumpf, Fen und Schilf umfasst. Es gibt einige Eiche und Haselpeeling mit Heide auf den trockeneren Nordhängen hinter dem Lough und es gibt auch Küstenheide auf der Carrickalagh Landzunge. Sescen Mór bedeutet wörtlich "großer Sumpf" und die sumpfige Ebene enthält einen Großteil der interessanten Flora und Fauna der Gegend. Südlich und westlich der flachen sumpfigen Ebene gibt es sandige Machair-Grasflächen, die sich zu hohen welligen Sanddünen entlang Trawmore Strand und Ballinreavy Strand entwickeln. Gnáthóga Ist córas duimhche seasta an ceantar seo den chuid mó ina bhfuil talamh féarach, machaire, dumhcha, Loch an tSeascainn Mhóir, machaire moing agus sraith ghiolcach thart air. Tá crainn dharach agus scrobarnach coil maraoin le fraoch ar na fánaí tirime ar an taobh thuaidh den loch agus tá fraoch cósta ar cheann tire Charraig Adhlactha. Ciallaíonn Seascann Mór bogach nó corrach mór agus ta fásra agus ainmhíthe suimiúla le fail ar chuid mhaith den mhachaire corrach seo. Ar an taobh theas agus thiar den mhachaire tá talaimh féir gainimh a éiríonn ansin i ndumhcha droimnigh arda le taobh trá na Trá Móire agus Trá Bhaile an Riabhaigh Vögel Ein Besuch zu jeder Jahreszeit ist immer interessant für die Vogelwelt. Im Winter eine kleine Herde von Greensland White Fronted Gänse fressen hier ungestört. Chough und Twite füttern auch hier im Winter. Brent Goose, Whooper Swan, Wigeon, Tufted Duck, Goldeneye und Golden Plover sind weitere Winterbesucher. Lapwing, Mallard, Teal, Snipe und Mute Swan sind das ganze Jahr über zu finden, ebenso Linnet, Skylark, Meadow Pipit, Stonechat und Reed Bunting. Sommerbesucher sind die Grasshopper, Sedge und Willow Warblers und Wheatear, Swallow und Cuckoo. Raubvögel nutzen diesen riesigen, ungestörten Ort zur Jagd. Ein Ist fiú go mór cuairt a thabhairt anseo ag am ar bith den bhliain chun an éanlaith shuimiúil a fheiceáil. Ich rith an gheimhridgh bíonn scata Géanna le Brollaigh Bhána ón Ghraonlainn a chothú ann. Bionn an Cág Deargchosach agus an Ghleoiseach Shléibhe ann as gheimhreadh. Ist cuairteoirí geimhridgh eile iad an Ghé Dhubh, an Eala Ghlórach, an Lacha rua, an Lacha Dhubh, an Feadóg Shléibhe agus Feadóg na Súile Óire. Chítear an Pilibín, an Mallard, an Phraslacha, an Naoscach, an Eala Bhalbh ann I rith nab liana chomh maith leis an Ghleoiseach, an Fhuiseog, an Riabhógmhóna, an Chloch Dearg agus an Ghealóg Dhúcheannach. Ich rith an tsamhraidh bionn an Dreoilin Teaspaigh, an Chíb, an Ceolaire Sailí, an Chlochrán, an Fhainleog agus an Chuach le feiceáil ann. Úsáideann éin chreiche an láithreán leathan oscaillte seo mar thalamh seilge. Pflanzen Die feste Düne und Machair werden geschafft, ihren Artenreichtum zu verbessern. Rinder weiden nur in den Wintermonaten ausgiebig. Orchideenarten umfassen die Marsh Helleborine, Bee Orchid, Frosch Orchidee und die seltene irische Orchidee. Es gibt eine Abfolge von Farben während der Sommermonate in den Dünen und auf dem Sumpf, von Gelb und Weiß im Frühling bis zu den Rosa und Purpur des Spätsommers. Zu den in der Gegend verzeichneten Seltenheiten gehören das aquatische schlanke Naiad und Pfeifenwort, das winzige Petalwort, auch Quillwort, hoary whitlow Gras und viele Steinwortarten. Plandaí Riaraítear na dumhcha seasta agus an machaire chun siabhreas na ngnéithe a mhéadu. Bíonn eallach ag iníorgo tréan anseo i rith míonna an gheimhridh amháin. Ich measc an ngnéithe magairlíne tá Cuacihín Corraigh, Magairlín na mBeach, Magairlín an Ioscáin agus Magairlín Éireannach atá neamhchoitianta. Bíonn athraithe datha trí mhíonna an t-samhraidh sna dumhcha agus ar an machaire ó dhath buí agus bán an earraigh go dathanna bándearga agus corcra dheireadh an t-samhraidh. Ich measc na ngnéithe neamhchoitianta a rinneadh cuntas orthu sa cheantar seo tá nimfigh uisce, píbín uisce, tursarraing chleite, bosán anagair agus tursarraing chloiche. Tiere Kaninchen, Dachse und Füchse sind die häufigsten Säugetiere in Sheskinmore aufgezeichnet. Otter wurden im lough gesehen. Frosch und Molch brüten in und um die Dünenschluchten und die gewöhnliche Echse brütet an den trockeneren Hängen. Die geschützte kleine Sumpfschneckenart Vertigo geyeri findet sich im Fenlebensraum westlich des Loughs. Die Gegend ist auch bemerkenswert für die Vielfalt der Schmetterlinge und Libellen, die hier brüten. Marsh fritillary und schmuddelige Skipper beide brüten in Sheskinmore zusammen mit 18 anderen Schmetterlingsarten. Sheskinmore Lough und die damit verbundenen Feuchtgebiete sind der artenreichste Standort in Donegal für Libellen und Damselflies. Fünfzehn Arten wurden registriert, die interessanteste ist der Schwarzschwanz-Skimmer und die kleine blaue Spitze. 2 Ainmhithe Ist iad coiníní, broic agus sionnaigh na siní ist coitianta ar an t-Seascann Mór. Chonacthas dobharchúnna sa loch. Bíonn an frog agus an t-earc luachra ag síolrú thart ar na dumhcha agus an t-earc coitianta ag síolrú ar na fánaí tirime. Faightear seilidí beaga corraigh. Vertigo geyeri atá cosanta sa ghnáthóg moinge taobh thiar den loch. Tá cáil ar an cheantar seo as ucht ilghnéitheachta na bhfeileacán agus na snatháidí móra a shíolraíonn anseo. Bíonn Fritileáin corraigh agus Preabairí modartha ag síolrú ar an SEascann Mór maraon le ocht ngné déag d’fheileacán. Bíonn níos mó gnéithe de shnatháidí móra agus cuileoga daimsil le fail I gceantar Loch an t-Seascainn Mhóir agus na talaimh fliucha thart air ná in áit ar bith eile i gCo. Dhún na nGall. Rinneadh cuntas oifigiúil ar cúig ghné déag díobh agus Snatháid an Eireaball Dhuibh agus Snatháid Bheag an Bhairr Ghoirm ar na cinn is suimiúla. Verwaltung Das Grundstück wird von NPWS verwaltet, um seine Biodiversität zu maximieren. Das Gebiet ist reich an Sumpf- und Dünenpflanzen und unterstützt eine Vielzahl von Wirbellosen und Vögeln. Das Getreidefeld am Eingang von Mullyvea wurde zuerst in [datierte Quelle] gepflanzt, um Finken und Buntings während der Wintermonate zu füttern. Ein weiteres Grundstück ist für Sandfield geplant. Die Website ist Winter grasen Blumenvielfalt zu fördern und Kuhpats sind auch eine Quelle der Nahrung für die Nahrungssuche. Die Besatzraten werden regelmäßig überprüft und Pferde können manchmal auf dem Gelände weiden. Zur Bekämpfung von Bracken wurden verschiedene Methoden ausprobiert. Eine Schleuse ist vorhanden, um den Wasserstand am Lough zu kontrollieren, um die schlanke Naiad-Population zu schützen. In [datierter Quelle] McGlincheys Haus in Sandfield wurde vollständig restauriert und wird jetzt als Feldstudienzentrum genutzt. Bainistíocht Riaraíonn an NPWS an eastát se chun uasmhéid éagsúlacht bheatha a fháil. Ist ceantar saibhir é le plandaí seascainn agus dumhcha a chothaíonn éagsúlacht leathan éan agus ainmhíthe gan cnámh droma. Cuireadh arbhar don chéad uair I [datiert Quelle] ag bealach insteach ag Mullach Bheitheach chun na gealóga a bheathú i rith an gheimhridh. Tá plean do phlota eile arbhair ag Achadh an Ghainimh. Cuirtear eallach ag iníor ar an láitrhreán sa gheimhreadh chun cuidiú leis an éagsúlacht bláthanna agus is foinse bia an cac bó do na cáig dhearg-chosacha. Coinnítear súil ar an stoc ó am go ham agus b’fheider go ligtar do chapaill a bheith ar fhéar anseo chomh maith. Úsáideadh dóigheanna éagsúla chun smacht a chur ar an raithneach. Cuireadh loc-chomhla ann chun leibhéil an uisce a chosaint. Ich [datiert Quelle] coíríodh Teach Mhic Loinsigh in Achadh an Ghainimh agus tá sé in úsáid mar ionad staidéir amuigh faoin aer. Zugang & Sicherheit Es gibt drei signierte Access Points. Der Haupteingang befindet sich am Mullyvea-Tor gegenüber dem Kiltooris Lough. Es gibt Zugang von der Ostseite sowohl bei Murveagh und Sandfield der R261. Wanderer sollten vorsichtig sein, Tiere zwischen Oktober und Mai zu weiden, und Hunde sollten jederzeit an der Leine und unter Kontrolle gehalten werden. Ein Teil des Landes auf dem Gelände ist immer noch in Privatbesitz, also achten Sie darauf, Tore zu schließen und keine Mauern oder Zäune zu beschädigen. Entsprechende Wanderkleidung sowie eine Karte und ein Kompass werden empfohlen. Alle schädlichen Aktivitäten sollten NPWS im Gleanveagh-Nationalpark 074 -9137090 oder NPWS in Ballinafad, Co. Sligo, 071 9666700 Bealach Isteach agus Sábháilteacht gemeldet werden. Tá trí bhealach isteach le comharthaí. Tá an príomhbhealach isteach ag geata an Mhullaigh Bheitheach os coinne Loch Chill Dorais. Tá bealach isteach ón taobh thoir ag Muirbheitheach Bheitheach agus Achadh an Ghainimh ón R261. Ba choir do shiúlóirí o bheith cúramach roimh ainmhíthe ar fhéar ó Dheireadh Fómhair go Bealtaine agus ba cheart madaí a choinneáil ar éill agus faoi smacht an t-am uilig. Ná dean dearmad na geataí a dhruid ná dochar a dhéanamh do bhallaí agus do fhálta. Moltar do shiúlóirí éadai foirstineacha a chaítheamh agus léarscáil agus compass a thabhairt leo. Má bhíonn imeachtaí a chuisíonn dochar ba choir fios a chur ar an tSeirbhís Páirceanna Náisiúnta agus Fiadhúlra I nGleann Bheitheach 074-9137090 nó ag Baile an Atha Fada, Co. Shligigh 071- 9666700 Gegründet: Eigentum: Staatseigentum', 'Sheskinmore ist ein großes Gebiet aus Sanddünen, See und Marsch zwischen Kiltooris und dem Strand von Ballinreavy, nordwestlich von Ardara in Co. Donegal. Es ist besonderes Schutzgebiet, Vogelschutzgebiet und Wasservogelreservat und leicht über das Tor in Mullyvea gegenüber dem Kiltooris Lough erreichbar. Das Gelände besteht vor allem aus festliegenden Dünen mit Machair-Grasland, Dünentälern, dem Sheskinmore Lough und den umliegenden Marschen, Niedermooren und Schilfflächen. Im Winter äst hier ein kleiner Trupp Blässgänse, dazu Alpenkrähen und Berghänflinge; zu den Orchideen zählen Sumpf-Stendelwurz, Bienen-Ragwurz und die seltene Irische Orchidee. Das Reservat wird vom NPWS betreut und im Winter beweidet, um die Pflanzenvielfalt zu fördern. Zwischen Oktober und Mai ist auf Weidetiere zu achten; Hunde sind an der Leine zu führen und Tore zu schließen, da ein Teil des Geländes in Privatbesitz ist.'),
  ('de', 'sila-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sila National Park (italienisch: Parco nazionale della Sila) ist ein italienischer Nationalpark in Kalabrien auf dem Sila Plateau. Es wurde 1997 gegründet und umfasst etwa 74.000 Hektar (180.000 Acres). Seine höchsten Berge sind Botte Donato (1.928 m) in Sila Grande und Gariglione (1.764 m) in Sila Piccola. Der Park wurde mit dem Regionalerlass vom 14. November [datiert Quelle] gegründet und umfasst eine eigene Verwaltungsagentur. Der Park umfasst die Gebiete, die früher Teil des Kalabrien-Nationalparks (1968) waren, und schützt Gebiete von großem Umweltinteresse in Sila Piccola, Sila Grande und Sila Greca, für insgesamt 736,95 Quadratkilometer (284,54 Quadratkilometer), in 21 Gemeinden (comuni) und 6 "Berggemeinschaften" (comunità montane) in den drei kalabrischen Provinzen Catanzaro, Cosenza und Crotone.', 'Der Nationalpark Sila (italienisch: Parco nazionale della Sila) liegt in Kalabrien auf der Hochebene der Sila. Er wurde 1997 gegründet und umfasst rund 74.000 Hektar. Die höchsten Berge sind der Botte Donato (1.928 m) in der Sila Grande und der Gariglione (1.764 m) in der Sila Piccola. Der Park schließt Gebiete des früheren Nationalparks Kalabrien (1968) ein und schützt ökologisch wertvolle Landschaften in Sila Piccola, Sila Grande und Sila Greca in 21 Gemeinden der Provinzen Catanzaro, Cosenza und Crotone.'),
  ('de', 'sjunkhatten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sjunkhatten National Park wurde in [datierter Quelle] im Bezirk Nordland, Norwegen, gegründet. Der Park besteht aus einem ständig geschützten 417,5-Quadratkilometer-Gebiet, darunter 39,8-Quadratkilometer-Seegebiet in der Gemeinde Bodø, der Gemeinde Fauske und der Gemeinde Sørfold. Der Park befindet sich auf einer Halbinsel zwischen dem Sørfolda-Fjord und Saltfjord, einschließlich Gletscherlandschaft, Höhlen und Wassersysteme, Fjorde, der große See Heggmovatnet, seltene Tierarten und kulturelles Erbe.', 'Der Sjunkhatten-Nationalpark liegt in der Provinz Nordland in Norwegen. Er ist ein zusammenhängendes Schutzgebiet von 417,5 Quadratkilometern, davon 39,8 Quadratkilometer Meer, in den Gemeinden Bodø, Fauske und Sørfold. Der Park liegt auf einer Halbinsel zwischen dem Sørfolda-Fjord und dem Saltfjord und umfasst eine von Gletschern geformte Landschaft, Höhlen und Gewässersysteme, Fjorde, den großen See Heggmovatnet, seltene Tierarten und Kulturerbe.'),
  ('de', 'sjunkhatten-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Sjunkhatten National Park wurde in [datierter Quelle] im Bezirk Nordland, Norwegen, gegründet.', 'Ein 417,5 km2 großer Nationalpark auf einer Halbinsel zwischen Sørfolda und Saltfjorden in Nordland, Norwegen.'),
  ('de', 'soroya', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sørøya oder Sállan ist Norwegens viertgrößte Insel in Bezug auf die Fläche und die größte in Finnmark. Die 811 Quadratkilometer große Insel ist zwischen der Gemeinde Hasvik und der Gemeinde Hammerfest aufgeteilt. Es wird oft behauptet, "eine der schönsten" der Inseln in Norwegen zu sein. In [datiert Quelle] war die Bevölkerung der Insel 1.100.', 'Sørøya (samisch: Sállan) ist nach Fläche die viertgrößte Insel Norwegens und die größte der Provinz Finnmark. Die 811 Quadratkilometer große Insel ist zwischen den Gemeinden Hasvik und Hammerfest aufgeteilt und gilt oft als „eine der schönsten“ Inseln Norwegens.'),
  ('de', 'southern-black-forest-biosphere-area', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Das Schwarzwald-Biosphärengebiet liegt im Südschwarzwald und wurde in [datierter Quelle] eingerichtet.', 'Ein UNESCO-Biosphärenreservat im Südschwarzwald mit Sitz der Geschäftsstelle in Schönau.'),
  ('de', 'watchmaking-doubs-regional-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Der regionale Naturpark Doubs Horloger ist ein regionaler Naturpark in Ostfrankreich, gegründet am 4. September [datiert Quelle]. Es liegt im Departement Doubs in der Region Burgund-Franche-Comté und erstreckt sich entlang der französisch-schweizerischen Grenze und grenzt an den regionalen Naturpark Doubs auf der Schweizer Seite.', 'Der Regionale Naturpark Doubs Horloger liegt im Osten Frankreichs im Departement Doubs (Region Bourgogne-Franche-Comté). Er erstreckt sich entlang der französisch-schweizerischen Grenze und grenzt auf Schweizer Seite an den Regionalen Naturpark Doubs.'),
  ('en', 'are', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Åre is a locality and one of the leading Scandinavian ski resorts situated in Åre Municipality, Jämtland County, Sweden with 3,200 inhabitants in [dated source]. It is, however, not the seat of the municipality, which is Järpen. 25% of the local economy is based on tourism, most notably the downhill skiing and biking resorts in Åre, Duved and Storlien. The growth in tourism has resulted in the development of hotels, recreational and shopping opportunities in the area.', 'Åre is a locality and one of Scandinavia''s leading ski resorts, in Åre Municipality, Jämtland County, Sweden. It is not the seat of the municipality, which is Järpen. Around 25% of the local economy is based on tourism, notably the downhill skiing and biking resorts in Åre, Duved and Storlien, and the growth in tourism has brought hotels, recreation and shopping to the area.'),
  ('en', 'ariege-pyrenees-regional-natural-park', 'seo_description', 'seo_description', null, 'REWRITE', 'With about 2,468 km2, it includes 138 communes since 1 January [dated source] and 46,000 inhabitants.', 'A regional natural park of about 2,468 km2, covering some 40% of the Ariège department in the Pyrenees.'),
  ('en', 'ariege-pyrenees-regional-natural-park', 'tagline', 'tagline', null, 'REWRITE', 'With about 2,468 km2, it includes 138 communes since 1 January [dated source] and 46,000 inhabitants.', 'A regional natural park of about 2,468 km2, covering some 40% of the Ariège department in the Pyrenees.'),
  ('en', 'baie-de-somme-picardie-maritime', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Bay of Somme Regional Natural Park - Picardie maritime is a regional natural park located in the department of the Somme, created in [dated source] at the initiative of the Hauts-de-France region. This is the 5th natural park in this area.', 'The Bay of Somme – Picardie maritime Regional Natural Park lies in the Somme department and was created at the initiative of the Hauts-de-France region. It is the fifth natural park in this region.'),
  ('en', 'basque-coast-unesco-global-geopark', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Basque Coast Geopark (Basque language: Euskal Kostaldeko Geoparkea), formally the Basque Coast UNESCO Global Geopark, is an area of the Basque Country in the north of Spain which became a member of the European Geoparks Network in [dated source], one of several Global Geoparks in Spain. It comprises 89 square kilometres of countryside with a 23 km long cliffed coast fronting the Bay of Biscay. Inland it comprises hilly country which reaches up to Sesiarte which is 755m above sea level. The main communities within the Geopark are Zumaia, Deba and Mutriku. The A8 Cantabrian motorway runs east–west through the Geopark.', 'The Basque Coast Geopark (Basque: Euskal Kostaldeko Geoparkea), formally the Basque Coast UNESCO Global Geopark, is an area of the Basque Country in northern Spain and a member of the European Geoparks Network, one of several Global Geoparks in Spain. It comprises 89 square kilometres of countryside with a 23 km cliffed coast on the Bay of Biscay. Inland, hilly country rises to Sesiarte at 755 m above sea level. The main communities are Zumaia, Deba and Mutriku, and the A8 Cantabrian motorway crosses the Geopark from east to west.'),
  ('en', 'bieszczady-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source], the national park became a UNESCO World Heritage Site .', 'Bieszczady National Park is Poland''s third-largest national park, in the far southeast of the country.'),
  ('en', 'bieszczady-national-park', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source], the national park became a UNESCO World Heritage Site .', 'Bieszczady National Park is Poland''s third-largest national park, in the far southeast of the country.'),
  ('en', 'black-forest-central-north-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Central/North Black Forest Nature Park (German: Naturpark Schwarzwald Mitte/Nord) is located in Baden-Württemberg in Germany. It covers an area of 3,750 km2 and was founded in December [dated source]. As of [dated source], it is the third-largest nature park in Germany.', 'The Central/North Black Forest Nature Park (German: Naturpark Schwarzwald Mitte/Nord) lies in Baden-Württemberg, Germany, and covers an area of 3,750 km2.'),
  ('en', 'boucles-de-la-seine-normande', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel régional des Boucles de la Seine Normande, formerly Parc naturel régional de Brotonne until [dated source], is a regional natural park created on 17 May 1974 and comprises 35 communes, covering 89,700 hectares, between Rouen and Le Havre. It is composed of 77 communes + 1 associated commune, Sandouville. Three municipalities have the status of entry-gate cities: Canteleu, Yvetot and Pont-Audemer. It has a wide variety of natural and human environments, as it extends over the Roumois, the Risle valley, the banks of the Seine downstream of Rouen with their small tributary valleys, the Brotonne loop, the marshes of the Estuary, the Vernier marsh, and the southern part of the country of Caux. These include:', 'The Parc naturel régional des Boucles de la Seine Normande, formerly the Parc naturel régional de Brotonne, is a regional natural park created on 17 May 1974 between Rouen and Le Havre, covering 89,700 hectares. Canteleu, Yvetot and Pont-Audemer are its gateway towns. It spans a wide variety of natural and human landscapes: the Roumois, the Risle valley, the banks of the Seine downstream of Rouen with their small side valleys, the Brotonne loop, the estuary marshes, the Vernier marsh and the southern Pays de Caux.'),
  ('en', 'breheimen-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Breheimen National Park is a national park that was established in [dated source].', 'Breheimen National Park covers 1,671 square kilometres of the Breheimen mountain range in Norway.'),
  ('en', 'breheimen-national-park', 'tagline', 'tagline', null, 'REWRITE', 'Breheimen National Park is a national park that was established in [dated source].', 'Breheimen National Park covers 1,671 square kilometres of the Breheimen mountain range in Norway.'),
  ('en', 'breheimen-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Breheimen National Park is a national park that was established in [dated source]. The park is located in Skjåk Municipality and Lom Municipality in Innlandet county and in Luster Municipality in Vestland county, Norway. The park covers 1,671 square kilometres of the Breheimen mountain range. The park encompasses some of the wettest and driest terrain in the country, with landscapes shaped over hundreds of thousands of years by glaciers, avalanches and other geological processes. Visitors encounter everything from lush transhumance‑farmed valleys to barren plateaus, soaring peaks and active glaciers.', 'Breheimen National Park lies in Skjåk and Lom municipalities in Innlandet county and in Luster Municipality in Vestland county, Norway. It covers 1,671 square kilometres of the Breheimen mountain range, including some of the wettest and driest terrain in the country, shaped over hundreds of thousands of years by glaciers, avalanches and other geological processes. Visitors find everything from lush valleys with summer farms to barren plateaus, soaring peaks and active glaciers.'),
  ('en', 'catalan-pyrenees-regional-natural-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Created in March [dated source], it is the first regional natural park in the Pyrenean Mountains.', 'The first regional natural park in the Pyrenees, covering the western third of the Pyrénées-Orientales.'),
  ('en', 'catalan-pyrenees-regional-natural-park', 'tagline', 'tagline', null, 'REWRITE', 'Created in March [dated source], it is the first regional natural park in the Pyrenean Mountains.', 'The first regional natural park in the Pyrenees, covering the western third of the Pyrénées-Orientales.'),
  ('en', 'conca-dorupatrimoniogolfe-de-saint-florent', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Conca d''Oru, the vineyards of Patrimonio - Gulf of Saint-Florent, received the Label Grand Site of France in March [dated source]. It is the seventeenth labeled site and the second in Corsica.', 'Conca d''Oru, the vineyards of Patrimonio and the Gulf of Saint-Florent hold the Grand Site de France label. It is the seventeenth labelled site in France and the second in Corsica.'),
  ('en', 'dajti-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Dajti Mountain National Park is a national park established in 1966 in central Albania, spanning an area of 293.84 km2 since [dated source]. The park is 40 km east of the Adriatic Sea and 26 km east of Tirana. The area is under shared jurisdiction between Albanian Agency of Protected Areas and Tirana Municipality Parks and Recreation Agency . It is adjacent to Shtamë Pass Nature Park to the northwest, Kraste-Verjon Protected Landscape to the west, and Mali me Gropa-Bizë-Martanesh Protected Landscape to the east. The park is marked by an extremely fragmented, rugged topography which creates favourable conditions for a great diversity of ecosystems and biodiversity.', 'Dajti Mountain National Park is a national park established in 1966 in central Albania, covering 293.84 km2. It lies 40 km east of the Adriatic Sea and 26 km east of Tirana and is managed jointly by the Albanian Agency of Protected Areas and the Tirana Municipality Parks and Recreation Agency. It borders Shtamë Pass Nature Park to the northwest, Kraste-Verjon Protected Landscape to the west and Mali me Gropa-Bizë-Martanesh Protected Landscape to the east. Its extremely fragmented, rugged topography favours a great diversity of ecosystems and wildlife.'),
  ('en', 'faerder-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Færder National Park is a national park in Færder Municipality in Vestfold county, Norway. It is mostly a marine park, and includes some islands and coastal areas to the east of the larger islands of Nøtterøy and Tjøme. To the east, the national park borders to the Ytre Hvaler National Park. Færder covers an area of 340 km2, of which 325 km2 is sea and 15 km2 is land. The park was established on 23 August [dated source]. The park includes large parts of the archipelago of Bolærne, as well as the protected Færder Lighthouse and the ruins of Store Færder Lighthouse with its associated protected buildings.', 'Færder National Park is a national park in Færder Municipality in Vestfold county, Norway. It is mostly a marine park, including islands and coastal areas east of the larger islands of Nøtterøy and Tjøme, and borders Ytre Hvaler National Park to the east. Færder covers 340 km2, of which 325 km2 is sea and 15 km2 is land. The park includes large parts of the Bolærne archipelago, the protected Færder Lighthouse and the ruins of Store Færder Lighthouse with its associated protected buildings.'),
  ('en', 'garrawilla-national-park-nsw', 'seo_description', 'seo_description', null, 'REWRITE', 'Garrawilla National Park was created in December [dated source].', 'Garrawilla National Park lies beside the Oxley Highway between Coonabarabran and Mullaley in New South Wales.'),
  ('en', 'garrawilla-national-park-nsw', 'tagline', 'tagline', null, 'REWRITE', 'Garrawilla National Park was created in December [dated source].', 'Garrawilla National Park lies beside the Oxley Highway between Coonabarabran and Mullaley in New South Wales.'),
  ('en', 'garrawilla-national-park-nsw', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Garrawilla National Park was created in December [dated source]. It covers an area of 937 hectares. This park is located on the northern side of the Oxley Highway approximately halfway between Coonabarabran and Mullaley in New South Wales, Australia.', 'Garrawilla National Park covers an area of 937 hectares. It lies on the northern side of the Oxley Highway, roughly halfway between Coonabarabran and Mullaley in New South Wales, Australia.'),
  ('en', 'grands-causses-regional-natural-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel régional des Grands Causses is a French regional natural park created on 6 May 1995 and renewed in [dated source]. Located in Occitanie, at the southern tip of the Central Massif, it covers the southern part of the Aveyron department and the northern part of the Hérault department.', 'The Parc naturel régional des Grands Causses is a French regional natural park created on 6 May 1995. Located in Occitanie at the southern tip of the Massif Central, it covers the southern part of the Aveyron department and the northern part of the Hérault department.'),
  ('en', 'harz-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source] Harz became the first National Park in Germany to cover two federal states; the eastern part', 'Harz National Park spans two federal states, from Herzberg to Bad Harzburg and Ilsenburg, rising to 1,141 m on the Brocken.')
